#!/usr/bin/env bash
# One-command install for Minakami Plugins (macOS, Linux, Git Bash on Windows).
# Installs every plugin into each agent runtime on PATH: Claude Code, Codex CLI, Grok Build, and pi.
# Re-running it brings everything to the latest version.
# Set MINAKAMI_RUNTIMES to a comma-separated subset (claude,codex,grok,pi) to install into only those.
set -uo pipefail

MARKETPLACE="war3water/Minakami_plugins"
MARKETPLACE_NAME="minakami-plugins"
PI_SOURCE="git:github.com/war3water/Minakami_plugins"

# >>> generated by scripts/sync-manifests.sh from .agents/plugins/marketplace.json; do not edit
PLUGINS=("agent-coord-bootstrap" "prompt-audit" "code-map" "code-cleanup")
SKILLS=("agent-coord-bootstrap:check-templates" "agent-coord-bootstrap:init-agent-coord" "agent-coord-bootstrap:review-readme" "prompt-audit:audit-prompt" "prompt-audit:check-sources" "code-map:code-map" "code-cleanup:code-cleanup")
# <<< generated

echo "Minakami Plugins installer"
echo "  marketplace: ${MARKETPLACE}"

FOUND=()
FAILURES=()

# use_runtime NAME LABEL: true when NAME is wanted (MINAKAMI_RUNTIMES) and on PATH; says why when not
use_runtime() {
  echo
  if [ -n "${MINAKAMI_RUNTIMES:-}" ]; then
    case ",$(printf '%s' "${MINAKAMI_RUNTIMES}" | tr -d ' ')," in
      *",$1,"*) ;;
      *) echo "[$1] left out by MINAKAMI_RUNTIMES"; return 1 ;;
    esac
  fi
  if ! command -v "$1" >/dev/null 2>&1; then
    echo "[$1] $2 not found on PATH - skipping"
    return 1
  fi
  echo "[$1] $2"
  FOUND+=("$1")
}

if use_runtime claude "Claude Code"; then
  # add succeeds on an already-registered marketplace without refreshing it, so always refresh;
  # the refresh also fails when add did not register it, which is the failure that matters
  claude plugin marketplace add "${MARKETPLACE}"
  if ! claude plugin marketplace update "${MARKETPLACE_NAME}"; then
    FAILURES+=("claude: marketplace add/update failed")
  fi
  for p in "${PLUGINS[@]}"; do
    echo "[claude] installing ${p}"
    if ! claude plugin install "${p}@${MARKETPLACE_NAME}"; then
      FAILURES+=("claude: install ${p} failed")
      continue
    fi
    # install leaves an already-installed plugin at its installed version; update brings it current
    if ! claude plugin update "${p}@${MARKETPLACE_NAME}"; then
      FAILURES+=("claude: update ${p} failed")
    fi
  done
fi

if use_runtime codex "Codex CLI"; then
  # same as above: add leaves an existing snapshot stale, so always upgrade it
  codex plugin marketplace add "${MARKETPLACE}"
  if ! codex plugin marketplace upgrade "${MARKETPLACE_NAME}"; then
    FAILURES+=("codex: marketplace add/upgrade failed")
  fi
  for p in "${PLUGINS[@]}"; do
    echo "[codex] installing ${p}"
    if ! codex plugin add "${p}@${MARKETPLACE_NAME}"; then
      FAILURES+=("codex: add ${p} failed")
    fi
  done
fi

if use_runtime grok "Grok Build"; then
  # Grok also loads the plugins installed in Claude Code (its Claude compatibility, on by default).
  # Install a plugin into Grok only when Grok doesn't already load it from there, so that no skill
  # is loaded twice. When Grok can't report what it loads, install nothing rather than risk duplicates.
  if ! seen=$(grok inspect --json 2>/dev/null); then
    FAILURES+=("grok: 'grok inspect --json' failed, so it's unknown which plugins Grok already loads; nothing was installed into Grok")
  else
    # one JSON object per line, so a plugin's name and path land on the same line
    seen=$(printf '%s' "${seen}" | tr -d '\r\n' | tr '{' '\n')
    listed=$(grok plugin list 2>/dev/null)
    for p in "${PLUGINS[@]}"; do
      if printf '%s\n' "${seen}" | grep "\"name\": *\"${p}\"" | grep -i "claude" | grep -q "${MARKETPLACE_NAME}"; then
        echo "[grok] ${p}: loaded from Claude Code"
      elif printf '%s\n' "${listed}" | grep -q ": ${p} \["; then
        echo "[grok] updating ${p}"
        grok plugin update "${p}" || FAILURES+=("grok: update ${p} failed")
      else
        echo "[grok] installing ${p}"
        grok plugin install "${MARKETPLACE}#${p}" --trust || FAILURES+=("grok: install ${p} failed")
      fi
    done
  fi
fi

if use_runtime pi "pi"; then
  # pi installs the whole repository as one package; its package.json points pi at every plugin's skills
  if pi list 2>/dev/null | grep -qi "github.com/war3water/Minakami_plugins"; then
    echo "[pi] updating the ${MARKETPLACE_NAME} package"
    pi update "${PI_SOURCE}" || FAILURES+=("pi: update failed")
  else
    echo "[pi] installing the ${MARKETPLACE_NAME} package"
    pi install "${PI_SOURCE}" || FAILURES+=("pi: install failed")
  fi
fi

if [ "${#FOUND[@]}" -eq 0 ]; then
  echo
  echo "No runtime to install into: none of claude, codex, grok, or pi was found on PATH,"
  echo "or MINAKAMI_RUNTIMES left them out. Install at least one and re-run this script."
  exit 1
fi

# Personal skill folders with a plugin skill's name shadow the plugin or load next to it.
STALE=()
for entry in "${SKILLS[@]}"; do
  s=${entry#*:}
  for d in "${CLAUDE_CONFIG_DIR:-$HOME/.claude}/skills" "${CODEX_HOME:-$HOME/.codex}/skills" \
           "$HOME/.agents/skills" "$HOME/.grok/skills" "${PI_CODING_AGENT_DIR:-$HOME/.pi/agent}/skills"; do
    if [ -e "$d/$s" ]; then STALE+=("$d/$s"); fi
  done
done
if [ "${#STALE[@]}" -gt 0 ]; then
  echo
  echo "WARNING: these personal skill folders have the same name as a plugin skill, so a runtime may load"
  echo "them instead of the plugin, or both. Remove them unless you keep them on purpose:"
  for s in "${STALE[@]}"; do
    echo "  - ${s}"
  done
fi

if [ "${#FAILURES[@]}" -gt 0 ]; then
  echo
  echo "FAILED steps:"
  for f in "${FAILURES[@]}"; do
    echo "  - ${f}"
  done
  exit 1
fi

echo
echo "Done. Restart any running agent session to load the new versions."
echo "Start a skill with:"
for r in "${FOUND[@]}"; do
  case "$r" in
    claude) echo "  Claude Code: /<plugin>:<skill>, e.g. /code-cleanup:code-cleanup" ;;
    codex)  echo "  Codex CLI:   type \$ and pick the skill, e.g. \$code-cleanup (interactive sessions only)" ;;
    grok)   echo "  Grok Build:  /<skill>, or /<plugin>:<skill> when two skills share a name" ;;
    pi)     echo "  pi:          /skill:<skill>, e.g. /skill:code-cleanup" ;;
  esac
done
echo "Skills in each plugin:"
for p in "${PLUGINS[@]}"; do
  names=""
  for entry in "${SKILLS[@]}"; do
    if [ "${entry%%:*}" = "${p}" ]; then names="${names:+${names}, }${entry#*:}"; fi
  done
  echo "  ${p}: ${names}"
done
